"""Snapping span times to a fixed step for payroll."""

from typing import List

from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step}")


def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step, halves round up."""
    return (2 * minute + step) // (2 * step) * step


def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def _snapped(span: Span, step: int) -> Span:
    return Span(
        _snap(span.start, step), _snap(span.end, step)
    )


def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    start, end = _clock(span.start), _clock(span.end)
    return f"{start}-{end} ({hours}h {rest}m)"


# ---
def round_spans(spans: List[Span], step: int) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    _check_step(step)
    return [
        _label(_snapped(item, step))
        for item in spans
    ]

